pub fn sample_exact(degree: impl Into<PolynomialDegree>) -> Self {
    let degree = degree.into();
    match degree {
        PolynomialDegree::Infinity => Polynomial {
            coefficients: vec![Scalar::zero()],
        },
        PolynomialDegree::Finite(deg) => {
            let mut coefficients = vec![Scalar::random(); (deg + 1) as usize];
            coefficients[0] = Scalar::random(); // Ensure the constant term is non-zero
            Polynomial { coefficients }
        }
    }
}
